#include <iostream>
#include <limits>

bool multiplicar_comprobado(int a, int b, int& resultado) {
    // Este punto de partida conserva el dominio no negativo anterior.
    // Amplia la funcion para cumplir el nuevo contrato.
    if (a < 0 || b < 0) {
        return false;
    }
    if (a == 0 || b == 0) {
        resultado = 0;
        return true;
    }

    const int maximo = std::numeric_limits<int>::max();
    if (a > maximo / b) {
        return false;
    }

    resultado = a * b;
    return true;
}

int main() {
    int caso = 0;
    if (!(std::cin >> caso)) {
        return 1;
    }

    const int maximo = std::numeric_limits<int>::max();
    const int minimo = std::numeric_limits<int>::lowest();
    int a = 0;
    int b = 0;
    int esperado = 17;

    switch (caso) {
    case 1:
        a = minimo;
        b = 1;
        esperado = minimo;
        break;
    case 2:
        a = minimo;
        b = -1;
        break;
    case 3:
        a = -1;
        b = minimo;
        break;
    case 4:
        a = -maximo;
        b = -1;
        esperado = maximo;
        break;
    case 5:
        a = maximo;
        b = -2;
        break;
    case 6:
        a = minimo;
        b = 2;
        break;
    case 7:
        a = maximo;
        b = 2;
        break;
    case 8:
        a = minimo;
        b = 0;
        esperado = 0;
        break;
    case 9:
        a = 0;
        b = minimo;
        esperado = 0;
        break;
    case 10:
        a = 7;
        b = -6;
        esperado = -42;
        break;
    default:
        return 1;
    }

    int resultado = 17;
    const bool aceptado = multiplicar_comprobado(a, b, resultado);

    std::cout << "Aceptado=" << aceptado << '\n';
    std::cout << "Coincide=" << (resultado == esperado) << '\n';
    std::cout << "Conservado=" << (resultado == 17) << '\n';

    return 0;
